package com.autocare.platform.order;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class JdbcPointExchangeOffersTest extends JdbcPointExchangesTest {
 PointExchangeOffers offers;
 @BeforeEach void offerService(){offers=new PointExchangeOffers(db,catalog,ledger,true);}
 Map<?,?> item(){return (Map<?,?>)((List<?>)offers.list(owner,1).get("items")).get(0);}
 String reason(){return item().get("eligibility").toString();}
 @Test void unconfiguredStoppedAndDraftCatalogAreNotInventedOrLeaked(){var empty=offers.list(owner,1);assertEquals(0L,empty.get("total"));assertEquals(0L,empty.get("balance"));assertEquals(List.of(),empty.get("items"));long p=offer(2,2,2);catalog.status(operator,p,key(),statusBody(2,"STOPPED"));assertEquals(0L,offers.list(owner,1).get("total"));assertEquals(0,count("point_exchange_record"));assertEquals(0,count("point_verified_account"));}
 @Test void actualOwnerBalanceScopeAndTemplateCountsFollowCommittedExchange(){earn(owner);long p=offer(4,2,3);assertEquals("ELIGIBLE",reason());var r=item();assertEquals(1L,((Number)((Map<?,?>)r.get("merchant")).get("id")).longValue());assertEquals(1L,((Number)((Map<?,?>)r.get("project")).get("id")).longValue());assertEquals("synthetic-A",((Map<?,?>)r.get("merchant")).get("name"));assertEquals(4L,((Number)r.get("stock_left")).longValue());assertEquals(0L,((Number)r.get("exchanged_count")).longValue());exchanges.exchange(owner,key(),request(p));assertEquals(5L,offers.list(owner,1).get("balance"));assertEquals(1L,((Number)item().get("exchanged_count")).longValue());assertEquals(2L,((Number)item().get("remaining_limit")).longValue());var other=(Map<?,?>)((List<?>)offers.list(peer,1).get("items")).get(0);assertEquals(0L,((Number)other.get("exchanged_count")).longValue());assertEquals("INSUFFICIENT_POINTS",other.get("eligibility"));assertFalse(db.json(offers.list(owner,1)).contains("identity_session"));assertFalse(db.json(offers.list(owner,1)).contains("submission_key"));}
 @Test void legacyAndPendingAreNotPayableAndReadNeverCreditsOrIssues(){long p=offer(4,2,3);jdbc.update("UPDATE user SET point_balance=999999 WHERE id=1");checkin(policy("CHECK_IN"));var read=offers.list(owner,1);assertEquals(0L,read.get("balance"));assertEquals("REVIEW_REQUIRED",read.get("legacy_state"));assertEquals("INSUFFICIENT_POINTS",reason());assertEquals(0,count("point_verified_entry"));assertEquals(0,count("coupon_issue"));assertEquals(0,count("point_exchange_record"));assertEquals(999999,jdbc.queryForObject("SELECT point_balance FROM user WHERE id=1",Integer.class));}
 @Test void earningSwitchDoesNotDisableExchangeButIdentityAndExchangeSwitchDo(){earn(owner);offer(2,2,2);var withoutEarning=new PointExchangeOffers(db,catalog,new PointLedger(db,policies,"test-app",false,false),true);assertEquals(true,withoutEarning.list(owner,1).get("exchange_available"));assertEquals(false,new PointExchangeOffers(db,catalog,ledger,false).list(owner,1).get("exchange_available"));assertEquals("EXCHANGE_UNAVAILABLE",((Map<?,?>)((List<?>)new PointExchangeOffers(db,catalog,ledger,false).list(owner,1).get("items")).get(0)).get("eligibility"));jdbc.update("UPDATE auth_session SET point_identity_source='TEST' WHERE id=?",owner.session());assertEquals(false,offers.list(owner,1).get("exchange_available"));assertEquals("EXCHANGE_UNAVAILABLE",reason());jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->offers.list(owner,1)));}
 @Test void missingEvidencePoolChangesAndInactiveProjectHaveDistinctNonActionableReasons(){earn(owner);long p=offer(4,2,3),c=ReservationStore.number(catalog.row(p,false),"coupon_id");jdbc.update("UPDATE merchant_project SET on_shelf=0 WHERE id=1");assertEquals("SOURCE_UNAVAILABLE",reason());assertNull(item().get("merchant"));assertNull(item().get("project"));jdbc.update("UPDATE merchant_project SET on_shelf=1 WHERE id=1");coupons.pool(operator,c,key(),json.createObjectNode().put("selected",false).put("expected_pool_revision",1));assertEquals("SOURCE_CHANGED",reason());assertNull(item().get("project"));jdbc.update("DELETE FROM coupon_publication WHERE coupon_id=?",c);assertEquals("SOURCE_UNKNOWN",reason());assertEquals(7,balance());assertEquals(0,count("point_exchange_record"));}
 @Test void zeroStockQuotaAndInsufficientBalanceAreComputedWithoutIssuing(){earn(owner);long p=offer(3,2,1);exchanges.exchange(owner,key(),request(p));assertEquals("LIMIT_REACHED",reason());long c=ReservationStore.number(catalog.row(p,false),"coupon_id");catalog.status(operator,p,key(),statusBody(2,"STOPPED"));long replacement=directory(c,2,1);assertEquals("LIMIT_REACHED",reason());assertEquals(1L,((Number)item().get("exchanged_count")).longValue());catalog.status(operator,replacement,key(),statusBody(2,"STOPPED"));long empty=offer(1,2,2),emptyCoupon=ReservationStore.number(catalog.row(empty,false),"coupon_id");coupons.claim(peer,key(),claimBody(emptyCoupon));assertEquals("OUT_OF_STOCK",reason());assertEquals(5,balance());assertEquals(1,count("point_exchange_record"));}
 @Test void quoteWindowBoundariesAreExplicitAndSubmissionStillRechecksChangedSource(){earn(owner);long p=offer(2,2,2);var at=clock.value;jdbc.update("UPDATE point_exchange_catalog SET valid_from=? WHERE id=?",ReservationStore.time(at.plusSeconds(60)),p);assertEquals("NOT_STARTED",reason());clock.value=at.plusSeconds(60);assertEquals("ELIGIBLE",reason());long c=ReservationStore.number(catalog.row(p,false),"coupon_id");coupons.status(merchant,c,key(),statusBody(2,"STOPPED"));assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));assertEquals("SOURCE_UNAVAILABLE",reason());clock.value=at.plusSeconds(1800);assertEquals("EXPIRED",reason());assertEquals(7,balance());}
 @Test void paginationAndCurrentSessionAreBoundedAndDoNotExposeOwnerSelectors(){for(int i=0;i<21;i++)offer(1,2,1);assertEquals(20,((List<?>)offers.list(owner,1).get("items")).size());assertEquals(1,((List<?>)offers.list(owner,2).get("items")).size());assertEquals(21L,offers.list(owner,2).get("total"));assertEquals(List.of(),offers.list(owner,3).get("items"));assertThrows(Exception.class,()->offers.list(owner,0));assertThrows(Exception.class,()->offers.list(owner,1000001));assertEquals(0,count("point_exchange_record"));}
}
